import Header from "../../../Layout/header";
import React, { useEffect, useState } from "react";
import TableTitle from "../../Form/TableTitle";
import { apiUrls } from "../../../utils/apiUrls";
import { callAPI } from "../../../utils/apiUtils";
import {
  ApiLoder,
  ErrorMessage,
  HasPermission,
  SuccessMessage,
} from "../../../helpers/common";
import PartnerDropdown from "../../../helpers/PartnerDropdown";
import { TablePagination } from "@mui/material";
import ProductTypeDropdown from "../../../helpers/ProductTypeDropdown";
import { defaultConfig } from "../../../config";
import { useParams } from "react-router-dom";

export default function ProductEdit() {
  const [tenantList, setTenantList] = useState([]);
  const [loder, setLoader] = useState(false);
  const [page, setPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [paginatedItems, setPaginatedItems] = useState(0);
  const [expandedMilestone, setExpandedMilestone] = useState(null);
  const [expandedProduct, setExpandedProduct] = useState(null);
  const [price, setPrice] = useState(0);
  const [filter, setFilter] = useState({
    tenantId: "",
    productType: "",
  });

  const handleChangePage = (event, newPage) => {
    TenantlistAPI(
      filter.tenantId,
      newPage + 1,
      rowsPerPage,
      filter.productType
    );
    setPage(newPage + 1);
  };

  const handleChangeRowsPerPage = (event) => {
    let pageNo = 1;
    TenantlistAPI(
      filter.tenantId,
      pageNo,
      parseInt(event.target.value, 10),
      filter.productType
    );
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(pageNo);
  };

  const TenantlistAPI = async (tenantId, page, perpage, productType) => {
    let query = {
      tenantId: tenantId ? tenantId : "",
      searchValue: "",
      pageNo: page ? page : 1,
      recordPerPage: perpage ? perpage : 10,
      productType: productType ? productType : "",
    };
    setLoader(true);
    try {
      const apiResponse = await callAPI(
        apiUrls.GetAllManagePartnerProduct,
        {},
        "POST",
        query
      );
      setLoader(false);
      if (apiResponse?.data?.isSuccess) {
        setTenantList(apiResponse?.data?.data);
        setPaginatedItems(apiResponse?.data?.totalRecords);
      } else {
        setTenantList([]);
        ErrorMessage(apiResponse?.data?.message);
      }
    } catch (error) {
      setLoader(false);
    }
  };

  const handleChange = (e) => {
    let pageNo = 1;
    if (e.target.name === "tenantId") {
      TenantlistAPI(e.target.value, pageNo, rowsPerPage, filter.productType);
    }
    if (e.target.name === "productType") {
      TenantlistAPI(filter.tenantId, pageNo, rowsPerPage, e.target.value);
    }
    setPage(1);
    setFilter((val) => {
      return { ...val, [e.target.name]: e.target.value };
    });
  };

  const toggleMilestone = (index) => {
    setExpandedMilestone(expandedMilestone === index ? null : index);
  };

  const Getproduct = (id) => {
    TenantlistAPI(filter.tenantId, page, rowsPerPage, id);
    setFilter((val) => {
      return { ...val, productType: id };
    });
  };

  const param = useParams();

  useEffect(() => {
    if (param.tenantId) {
      TenantlistAPI(filter.tenantId, page, rowsPerPage, param.tenantId);
      setFilter((val) => {
        return { ...val, tenantId: param.tenantId };
      });
    }
    // eslint-disable-next-line
  }, []);

  // tenantId

  const handleChanges = (e, productIndex, field) => {
    const { value, type, checked } = e.target;
    const updatedTenantList = [...tenantList];
    updatedTenantList[productIndex][field] =
      type === "checkbox" ? checked : value;
    setTenantList(updatedTenantList);
  };

  // Handle nested optionType changes
  const handleOptionChange = (
    e,
    productIndex,
    optionIndex,
    optionTypeIndex,
    field
  ) => {
    const { value, type, checked } = e.target;
    const updatedTenantList = [...tenantList];
    updatedTenantList[productIndex].options[optionIndex].optionTypes[
      optionTypeIndex
    ][field] = type === "checkbox" ? checked : value;
    setTenantList(updatedTenantList);
  };

  const ProductAdd = async (data) => {
    try {
      setLoader(true);
      const apiResponse = await callAPI(
        apiUrls.ManagePartnersProducts,
        {},
        "POST",
        data
      );
      setLoader(false);
      if (apiResponse?.data?.isSuccess) {
        SuccessMessage(apiResponse?.data?.message);
        await TenantlistAPI(
          filter.tenantId,
          page,
          rowsPerPage,
          filter.productType
        );
      } else {
        ErrorMessage(apiResponse?.data?.message);
      }
    } catch (error) {
      setLoader(false);
    }
  };

  const handleSubmit = (index) => {
    const product = tenantList[index];
    const permission = HasPermission("SubTenantView");
    const payload = {
      productId: product.productId,
      ...(permission && {
        wholeSalePrice: product.wholeSalePrice || 0,
      }),
      ...(permission && {
        maxPartnerPrice: product.maxPartnerPrice || 0,
      }),
      ...(!permission && {
        partnerSellingPrice: product.partnerSellingPrice || 0,
      }),
      ...(permission && {
        isAvailable: product.isAvailable,
      }),
      ...(permission && {
        tenantId: filter.tenantId,
      }),

      ...(!permission && {
        markupType: product.markupType || "",
      }),
      ...(permission && {
        priceType: product.priceType || "",
      }),

      managePartnerProductOptions: product.options.flatMap((option) =>
        option.optionTypes.map((optionType) => ({
          optionId: option.optionId,
          optionTypeId: optionType.optionTypeId,

          ...(permission && {
            isAvailable: optionType.isAvailable,
          }),
          ...(permission && {
            wholeSalePrice: optionType.wholeSalePrice || 0,
          }),
          ...(permission && {
            maxPrice: optionType.maxPrice || 0,
          }),

          ...(!permission && {
            partnerSellingPrice: optionType.partnerSellingPrice || 0,
          }),
          ...(!permission && {
            markupOptionType: optionType.markupOptionType,
          }),
          ...(permission && {
            priceType: optionType.priceType,
          }),

          ...(permission && {
            tenantId: filter.tenantId,
          }),
        }))
      ),
    };
    ProductAdd(payload);
  };

  const Getmsrp = async (ProductId, index) => {
    let query = {
      ProductId: ProductId ? ProductId : "",
    };
    setLoader(true);
    try {
      const apiResponse = await callAPI(
        apiUrls.ManagePartnersProductsGetMSRP,
        query,
        "GET",
        {}
      );
      setLoader(false);
      if (apiResponse?.data?.isSuccess) {
        setExpandedProduct(index);
        setPrice(apiResponse?.data?.data);
      } else {
        ErrorMessage(apiResponse?.data?.message);
      }
    } catch (error) {
      setLoader(false);
    }
  };

  const handleClear = (index) => {
    const product = tenantList[index];
    const permission = HasPermission("SubTenantView");
  
    const updatedProduct = {
      productId: product.productId,
      manageProductId: product.manageProductId,
      productName: product.productName,
      ...(permission && { wholeSalePrice: 0 }),
      ...(!permission && { wholeSalePrice:  product.wholeSalePrice }),
      ...(permission && { maxPartnerPrice: 0 }),
      ...(!permission && { partnerSellingPrice: 0 }),
      ...(permission && { isAvailable: false }),
      ...(permission && { tenantId: filter.tenantId }),
      ...(!permission && { markupType: "Fixed" }),
      ...(permission && { priceType: "Fixed" }),
  
      options: product.options.map((option) => ({
        optionId: option.optionId,
        optionName: option.optionName,
        optionTypes: option.optionTypes.map((optionType) => ({
          optionId: option.optionId,
          optionTypeId: optionType.optionTypeId,
          optionTypeName: optionType.optionTypeName,
          price: optionType.price, // preserve original price if needed
          ...(permission && { wholeSalePrice: 0 }),
          ...(!permission && { wholeSalePrice: optionType.wholeSalePrice }),
          ...(permission && { maxPrice: 0 }),
          ...(permission && { isAvailable: false }),
          ...(permission && { priceType: "Fixed" }),
          ...(!permission && { partnerSellingPrice: 0 }),
          ...(!permission && { markupOptionType: "Fixed" }),
        })),
      })),
    };
  
    const updatedList = [...tenantList];
    updatedList[index] = updatedProduct;
    setTenantList(updatedList);
  };
  
  
  

  return (
    <>
      {loder && <ApiLoder />}
      <div className="intersight_content">
        <Header title="Manage Product" />
        <div className="body_content">
          <div className="contact-profile">
            <div className="d-flex align-items-center justify-content-between mb-30">
              <TableTitle title="Manage Product" />
            </div>

            <div className="d-block d-md-flex align-items-center gap-2 mb-30">
              <div className="filter-dropdown dropdown">
                <ProductTypeDropdown
                  value={filter.productType}
                  fn={handleChange}
                  load={true}
                  className="selectboxdropdown"
                  Getproduct={Getproduct}
                />
              </div>
              <div className="filter-dropdown dropdown">
                {HasPermission("SubTenantView") && (
                  <PartnerDropdown value={filter.tenantId} fn={handleChange} />
                )}
              </div>
            </div>
            <div className="task_table mb-30">
              <div className="table-responsive">
                <table className="table">
                  <thead>
                    <tr>
                      <th scope="col">SN</th>
                      <th scope="col">Product Name</th>
                      <th scope="col">MSRP</th>
                      {HasPermission("SubTenantView") && (
                        <th scope="col">IsVisible</th>
                      )}

                      <th scope="col">Price Type</th>

                      <th scope="col">Wholesale Price</th>
                      <th scope="col">
                        {" "}
                        {HasPermission("SubTenantView")
                          ? "Max Partner Price"
                          : "Selling Price"}
                      </th>
                      <th scope="col"></th>

                      <th scope="col" className="text-end">Action</th>
                    </tr>
                  </thead>
                  <tbody>
                    {tenantList?.map((val, i) => (
                      <React.Fragment key={i}>
                        <tr>
                          <td>{(page - 1) * rowsPerPage + i + 1}</td>
                          <td>{val?.productName}</td>
                          <td>
                            <span
                              className="color-blue"
                              style={{ cursor: "pointer" }}
                              onClick={() =>
                                expandedProduct === i
                                  ? setExpandedProduct(null)
                                  : Getmsrp(val.productId, i)
                              }
                            >
                              {expandedProduct === i
                                ? defaultConfig?.currencySign + price
                                : "Show"}
                            </span>
                          </td>
                          {HasPermission("SubTenantView") && (
                            <td>
                              <input
                                type="checkbox"
                                style={{ border: "1px solid #8f8b8b" }}
                                className="form-check-input"
                                checked={val.isAvailable}
                                onChange={(e) =>
                                  handleChanges(e, i, "isAvailable")
                                }
                              />
                            </td>
                          )}

                          {!HasPermission("SubTenantView") ? (
                            <td>
                              <select
                                class="form-select"
                                name="productType"
                                style={{ width: "137px" }}
                                value={val?.markupType}
                                onChange={(e) =>
                                  handleChanges(e, i, "markupType")
                                }
                              >
                                <option value="Fixed">Fixed</option>
                                <option value="Percentage">Percentage</option>
                              </select>
                            </td>
                          ) : (
                            <td>
                              <select
                                class="form-select"
                                name="productType"
                                style={{ width: "137px" }}
                                value={val?.priceType}
                                onChange={(e) =>
                                  handleChanges(e, i, "priceType")
                                }
                              >
                                <option value="Fixed">Fixed</option>
                                <option value="Percentage">Percentage</option>
                              </select>
                            </td>
                          )}

                          <td>
                            {HasPermission("SubTenantView") ? (
                              <input
                                type="number"
                                style={{ width: "120px" }}
                                className="form-control"
                                value={val?.wholeSalePrice}
                                onChange={(e) =>
                                  handleChanges(e, i, "wholeSalePrice")
                                }
                                disabled={!val.isAvailable}
                              />
                            ) : (
                              <p>
                                {" "}
                                {defaultConfig?.currencySign}{" "}
                                {val?.wholeSalePrice}
                              </p>
                            )}
                          </td>
                          <td>
                            {HasPermission("SubTenantView") ? (
                              <input
                                type="number"
                                className="form-control"
                                style={{ width: "120px" }}
                                value={val?.maxPartnerPrice}
                                disabled={!val.isAvailable}
                                onChange={(e) =>
                                  handleChanges(e, i, "maxPartnerPrice")
                                }
                              />
                            ) : (
                              <input
                                type="number"
                                className="form-control"
                                style={{ width: "120px" }}
                                value={val?.partnerSellingPrice}
                                onChange={(e) =>
                                  handleChanges(e, i, "partnerSellingPrice")
                                }
                              />
                            )}
                          </td>

                          {val?.options?.length > 0 ? (
                            <td
                              style={{ cursor: "pointer" }}
                              onClick={() => toggleMilestone(i)}
                            >
                              Show Options{" "}
                              <i
                                className="fa fa-angle-down me-2"
                                aria-hidden="true"
                              ></i>
                              
                            </td>
                          ) : (
                            <td>
                             
                            </td>
                          )}
                          <td className="text-end">
                          {HasPermission("ManageProductEdit") && (
                                 <>
                                 <img
                                  alt=""
                                  style={{cursor:"pointer"}}
                                  src="/image/submit.png"
                                   onClick={() => handleSubmit(i)}
                                 />
                                  <img
                                  alt=""
                                  style={{cursor:"pointer",marginLeft:"5px"}}
                                
                                  src="/image/cross.png"
                                   onClick={() => handleClear(i)}
                                 />
                                </>
                                 
                              )}
                          </td>
                        </tr>
                        {expandedMilestone === i && (
                          <React.Fragment>
                            {val?.options?.map((vals, ind) => (
                              <tr key={ind}>
                                <td
                                  style={{ padding: "0px" }}
                                  colSpan={
                                    HasPermission("SubTenantView") ? 9 : 8
                                  }
                                >
                                  <div className="product-table-new">
                                    <div className="d-flex align-items-center justify-content-between mb-3">
                                      <h2 className="body_heading width-left-border mb-0 new-table-heading">
                                        Option Name{" "}
                                        <span className="text-black">
                                          : {vals?.optionName}
                                        </span>
                                      </h2>
                                    </div>
                                    <table className="table">
                                      <thead>
                                        <tr>
                                          <th scope="col">Option Type</th>
                                          <th scope="col">Price</th>

                                          {HasPermission("SubTenantView") && (
                                            <th scope="col">IsVisible</th>
                                          )}
                                          <th scope="col">Price Type</th>
                                          <th scope="col">Wholesale Price</th>

                                          <th scope="col">
                                            {HasPermission("SubTenantView")
                                              ? "Max Price"
                                              : "Selling Price"}
                                          </th>
                                        </tr>
                                      </thead>
                                      <tbody>
                                        {vals?.optionTypes?.map(
                                          (valss, inds) => (
                                            <React.Fragment key={inds}>
                                              <tr>
                                                <td>{valss?.optionTypeName}</td>
                                                <td>
                                                  {defaultConfig?.currencySign}{" "}
                                                  {valss?.price}
                                                </td>
                                                {HasPermission(
                                                  "SubTenantView"
                                                ) && (
                                                  <td>
                                                    <input
                                                      type="checkbox"
                                                      style={{
                                                        border:
                                                          "1px solid #8f8b8b",
                                                      }}
                                                      disabled={!val.isAvailable}
                                                      checked={
                                                        valss?.isAvailable
                                                      }
                                                      onChange={(e) =>
                                                        handleOptionChange(
                                                          e,
                                                          i,
                                                          ind,
                                                          inds,
                                                          "isAvailable"
                                                        )
                                                      }
                                                      className="form-check-input"
                                                    />
                                                  </td>
                                                )}

                                                <td>
                                                  {HasPermission(
                                                    "SubTenantView"
                                                  ) ? (
                                                    <select
                                                      class="form-select"
                                                      name="productType"
                                                      style={{ width: "137px" }}
                                                      value={valss?.priceType}
                                                      onChange={(e) =>
                                                        handleOptionChange(
                                                          e,
                                                          i,
                                                          ind,
                                                          inds,
                                                          "priceType"
                                                        )
                                                      }
                                                    >
                                                      <option value="Fixed">
                                                        Fixed
                                                      </option>
                                                      <option value="Percentage">
                                                        Percentage
                                                      </option>
                                                    </select>
                                                  ) : (
                                                    <select
                                                      class="form-select"
                                                      name="productType"
                                                      style={{ width: "137px" }}
                                                      value={
                                                        valss?.markupOptionType
                                                      }
                                                      onChange={(e) =>
                                                        handleOptionChange(
                                                          e,
                                                          i,
                                                          ind,
                                                          inds,
                                                          "markupOptionType"
                                                        )
                                                      }
                                                    >
                                                      <option value="Fixed">
                                                        Fixed
                                                      </option>
                                                      <option value="Percentage">
                                                        Percentage
                                                      </option>
                                                    </select>
                                                  )}
                                                </td>

                                                <td>
                                                  {HasPermission(
                                                    "SubTenantView"
                                                  ) ? (
                                                    <input
                                                      type="number"
                                                      style={{ width: "120px" }}
                                                      className="form-control"
                                                      value={
                                                        valss?.wholeSalePrice
                                                      }
                                                      disabled={
                                                        !valss?.isAvailable
                                                      }
                                                      onChange={(e) =>
                                                        handleOptionChange(
                                                          e,
                                                          i,
                                                          ind,
                                                          inds,
                                                          "wholeSalePrice"
                                                        )
                                                      }
                                                    />
                                                  ) : (
                                                    <p>
                                                      {
                                                        defaultConfig?.currencySign
                                                      }{" "}
                                                      {valss?.wholeSalePrice}
                                                    </p>
                                                  )}
                                                </td>

                                                <td>
                                                  {HasPermission(
                                                    "SubTenantView"
                                                  ) ? (
                                                    <input
                                                      type="number"
                                                      className="form-control"
                                                      style={{ width: "120px" }}
                                                      value={valss?.maxPrice}
                                                      disabled={
                                                        !valss?.isAvailable
                                                      }
                                                      onChange={(e) =>
                                                        handleOptionChange(
                                                          e,
                                                          i,
                                                          ind,
                                                          inds,
                                                          "maxPrice"
                                                        )
                                                      }
                                                    />
                                                  ) : (
                                                    <input
                                                      type="number"
                                                      className="form-control"
                                                      style={{ width: "120px" }}
                                                      value={
                                                        valss?.partnerSellingPrice
                                                      }
                                                      onChange={(e) =>
                                                        handleOptionChange(
                                                          e,
                                                          i,
                                                          ind,
                                                          inds,
                                                          "partnerSellingPrice"
                                                        )
                                                      }
                                                    />
                                                  )}
                                                </td>
                                              </tr>
                                            </React.Fragment>
                                          )
                                        )}
                                      </tbody>
                                    </table>
                                  </div>
                                </td>
                              </tr>
                            ))}
                          </React.Fragment>
                        )}
                      </React.Fragment>
                    ))}
                    {(!tenantList || tenantList?.length === 0) && (
                      <tr>
                        <td
                          className="text-center border-0 no-records"
                          colSpan={7}
                        >
                          <img
                            src="/image/no-records.svg"
                            alt=" "
                            loading="lazy"
                            className="img-fluid"
                          />
                          <p className="font-14">No Product Found</p>
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
                {tenantList && tenantList?.length > 0 && (
                  <div className="d-flex align-items-center justify-content-end bottom_nav">
                    <nav aria-label="Page navigation example">
                      <ul className="pagination">
                        <TablePagination
                          rowsPerPageOptions={[5, 10, 15, 25, 100]}
                          component="div"
                          count={paginatedItems}
                          rowsPerPage={rowsPerPage}
                          page={page - 1}
                          onPageChange={handleChangePage}
                          onRowsPerPageChange={handleChangeRowsPerPage}
                        />
                      </ul>
                    </nav>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </>
  );
}
